		this.navigationButton = null;
	}


	@Subscribe
	public void onResourcePacksChanged(ResourcePacksChanged packsChanged)
	{
		SwingUtilities.invokeLater(() -> hubPanel.reloadResourcePackList(packsChanged.getNewManifest()));
	}
