import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.With;
import net.runelite.api.Client;

@Data
@With
@NoArgsConstructor
@AllArgsConstructor
public class WidgetOverride
{
	String name;

	int script = -1;
	int interfaceId = -1;
	int childId = -1;

	int type = -1;
	int newType = -1;

	int opacity = -1;
	int newOpacity = -1;

	int color = -1;
	int newColor = -1;

	List<Map.Entry<Integer, Integer>> varbits = new ArrayList<>();
	List<Integer> dynamicChildren = new ArrayList<>();

	boolean allChildren = false;
	boolean activeWidget = false;
	boolean explicit = false;

	public boolean isValid()
	{
		return script > -1 &&
			interfaceId > -1 &&
			childId > -1 &&
			color > -1;
	}

	public boolean checkVarbit(final Client client)
	{
		if (varbits.isEmpty())
		{
			return true;
		}

		for (var matcher : varbits)
		{
			if (client.getVarbitValue(matcher.getKey()) != matcher.getValue())
			{
				return false;
			}
		}

		return true;
	}
}

